function n(t){return String(t||"").replace(/[&<>"']/g,e=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[e]).split(/(```[\s\S]*?```|`[^`\n]+`)/g).map(e=>e.startsWith("```")?`<code>${e.slice(3,-3)}</code>`:e.startsWith("`")?`<code>${e.slice(1,-1)}</code>`:e.replace(/\*([^*\n]+)\*/g,"<strong>$1</strong>").replace(/_([^_\n]+)_/g,"<em>$1</em>").replace(/~([^~\n]+)~/g,"<s>$1</s>")).join("")}export{n as f};
